        group_stats = df.groupby(column)[numeric_columns].agg(['count', 'mean', 'std']).round(2)
        print(group_stats)
    else:
        group_stats = df.groupby(column)[numeric_columns].agg(['count']).round(2)
        print(group_stats)
else:
    # Compute min of column 'NumberofConcerts'
    print(f"🔧 Computing min of column 'NumberofConcerts'")

    show_stats = False
    column = 'NumberofConcerts'

